// Shape of the UI data generated by scripts/build-data.ts from data/*.json.
import type { Bait, Spot } from '../i18n/dictionaries.ts';

/** "HH:MM" or "MM-DD" window; `from > to` wraps over midnight / New Year. */
export type Window = { from: string; to: string };
/** `null` = unknown, `'always'` = any time / all year. */
export type Schedule = Window[] | 'always' | null;

export type UncertainField = 'time' | 'season' | 'bait';

export type Fish = {
  /** Stable progress key, never changes. */
  id: string;
  names: { cs: string; en: string };
  areas: string[];
  /** Exact spots inside an area, e.g. { "pinheira-beach": ["Pier"] }. */
  spots: Record<string, Spot[]>;
  time: Schedule;
  season: Schedule;
  rarity: 1 | 2 | 3 | 4 | 5;
  bait: Bait[];
  /** Ready-made label ("449 cm", "(448–449 cm)?"), `null` = unknown. Already carries its own "?". */
  length: string | null;
  /** Fields the UI marks with "?" (length is excluded, its label has the "?"). */
  uncertain: UncertainField[];
  /** Every fish has a glowing variant (user decision, not from the source). */
  glowing: true;
  /** Natural size of public/fish/<id>.webp, for layout without shifts. */
  img: { w: number; h: number };
};

export type AreaKind = 'area' | 'tournament' | 'backyard';

export type Area = {
  id: string;
  name: string;
  kind: AreaKind;
  spots: Spot[];
  count: number;
};
